def is_valid(isbn):
    chars = list(isbn.replace('-', ''))
    if chars and chars[-1] == 'X':
        chars[-1] = '10'
    if not len(chars) == 10 or not all(char.isdigit() for char in chars):
        return False
    indices = list(range(10, 0, -1))
    return sum(int(char) * idx for char, idx in zip(chars, indices)) % 11 == 0

class Garden:

    STUDENTS = [
        'Alice',
        'Bob',
        'Charlie',
        'David',
        'Eve',
        'Fred',
        'Ginny',
        'Harriet',
        'Ileana',
        'Joseph',
        'Kincaid',
        'Larry',
    ]
    PLANTS = {'C': 'Clover', 'G': 'Grass', 'R': 'Radishes', 'V': 'Violets'}

    def __init__(self, diagram, students=None):
        students = sorted(students or self.STUDENTS)
        front, back = diagram.splitlines()
        self.cups = {}
        for idx, student in enumerate(students[: len(front)]):
            start = idx * 2
            stop = start + 2
            self.cups.setdefault(student, [])
            self.cups[student].extend(
                self.PLANTS[plant] for plant in front[start:stop]
            )
            self.cups[student].extend(
                self.PLANTS[plant] for plant in back[start:stop]
            )

    def plants(self, student):
        return self.cups.get(student, [])

def maximum_value(maximum_weight, items):
    totals = [[0 for _ in range(len(items) + 1)]
              for _ in range(maximum_weight + 1)]

    for weight in range(1, maximum_weight + 1):
        for index, item in enumerate(items, 1):
            if item['weight'] <= weight:
                value = item['value'] + \
                        totals[weight - item['weight']][index - 1]

                value_without_item = totals[weight][index - 1]
                totals[weight][index] = max(value, value_without_item)
            else:
                totals[weight][index] = totals[weight][index - 1]
    return totals[maximum_weight][len(items)]

