class Luhn:
    def __init__(self, card_num):
        self.card_num = card_num
        self.checksum = -1
        digits = card_num.replace(' ', '')
        length = len(digits)
        if digits.isdigit() and length > 1:
            self.checksum = 0
            cadence = length % 2
            for idx, digit in enumerate(digits):
                num = int(digit)
                if idx % 2 == cadence:
                    num *= 2
                    if num > 9:
                        num -= 9
                self.checksum += num

    def valid(self):
        return self.checksum % 10 == 0

import re


def parse(markdown):
    lines = markdown.split('\n')
    html = ''
    in_list = False
    in_list_append = False
    for line in lines:
        result = parse_line(line, in_list, in_list_append)
        html += result['line']
        in_list = result['in_list']
        in_list_append = result['in_list_append']
    if in_list:
        html += '</ul>'
    return html


def wrap(line, tag):
    return '<{tag}>{line}</{tag}>'.format(line=line, tag=tag)


def check_headers(line):
    pattern = '# (.*)'
    for index in range(6):
        if re.match(pattern, line):
            return wrap(line[(index + 2):], 'h' + str(index + 1))
        pattern = '#' + pattern
    return line


def check_bold(line):
    bold_pattern = '(.*)__(.*)__(.*)'
    bold_match = re.match(bold_pattern, line)
    if bold_match:
        return bold_match.group(1) + wrap(bold_match.group(2), 'strong')\
            + bold_match.group(3)
    else:
        return None


def check_italic(line):
    italic_pattern = '(.*)_(.*)_(.*)'
    italic_match = re.match(italic_pattern, line)
    if italic_match:
        return italic_match.group(1) + wrap(italic_match.group(2), 'em')\
            + italic_match.group(3)
    else:
        return None


def parse_line(line, in_list, in_list_append):
    result = check_headers(line)

    list_match = re.match(r'\* (.*)', result)

    if list_match:
        if not in_list:
            result = '<ul>' + wrap(list_match.group(1), 'li')
            in_list = True
        else:
            result = wrap(list_match.group(1), 'li')
    else:
        if in_list:
            in_list_append = True
            in_list = False

    if not re.match('<h|<ul|<li', result):
        result = wrap(result, 'p')

    if list_match is None:
        result = re.sub('(.*)(<li>)(.*)(</li>)(.*)',
                        r'\1\2<p>\3</p>\4\5', result)

    while check_bold(result):
        result = check_bold(result)
    while check_italic(result):
        result = check_italic(result)

    if in_list_append:
        result = '</ul>' + result
        in_list_append = False

    return {
        'line': result,
        'in_list': in_list,
        'in_list_append': in_list_append
    }

def is_paired(input_string):
    counterparts = {')': '(', '}': '{', ']': '['}

    stack = []
    for char in input_string:
        if char in counterparts.values():
            stack.append(char)
        elif char in counterparts:
            if not stack:
                return False
            if stack.pop() != counterparts[char]:
                return False
    return not stack

class Matrix:
    def __init__(self, matrix_string):
        self.rows = [[int(number) for number in row.split()]
                     for row in matrix_string.split('\n')]
        self.columns = [list(tup) for tup in zip(*self.rows)]

    def row(self, index):
        return self.rows[index - 1]

    def column(self, index):
        return self.columns[index - 1]

from calendar import Calendar


def meetup(year, month, week, day_of_week):
    candidates = [date
                  for date in Calendar().itermonthdates(year, month)
                  if date.month == month
                  if date.strftime('%A') == day_of_week]
    return _choice(week)(candidates)


def _choice(week):
    if week == 'teenth':
        return lambda dates: next(date for date in dates if
                                  13 <= date.day <= 19)

    ordinals = ('first', 'second', 'third', 'fourth', 'fifth', 'sixth')
    day = -1 if (week == 'last') else (ordinals.index(week))

    def _func(dates):
        if day < len(dates):
            return dates[day]
        raise MeetupDayException('That day does not exist.')
    return _func


class MeetupDayException(ValueError):
    """Exception raised when the Meetup weekday and count do not result in a valid date.

    message: explanation of the error.

    """
    def __init__(self, message):
        self.message = message

from itertools import count
from math import sqrt


def prime(number):
    if number < 1:
        raise ValueError('there is no zeroth prime')

    known = []
    candidates = prime_candidates()

    def is_prime(candidate):
        sqrt_candidate = sqrt(candidate)
        for item in known:
            if item > sqrt_candidate:
                return True
            elif candidate % item == 0:
                return False
        return True

    while len(known) < number:
        next_one = next(candidates)
        if is_prime(next_one):
            known.append(next_one)

    return known[number - 1]


def prime_candidates():
    yield 2
    yield 3
    for number in count(6, 6):
        yield number - 1
        yield number + 1

NUM_ROWS = 4
NUM_COLS = 3


def split_ocr(ocr):
    return [[ocr[idx][NUM_COLS * jam:NUM_COLS * (jam + 1)] for idx in range(NUM_ROWS)]
            for jam in range(len(ocr[0]) // NUM_COLS)]


ALL = ['    _  _     _  _  _  _  _  _ ',
       '  | _| _||_||_ |_   ||_||_|| |',
       '  ||_  _|  | _||_|  ||_| _||_|',
       '                              ']

OCR_LIST = split_ocr(ALL)
OCR_LIST = [OCR_LIST[-1]] + OCR_LIST[:9]


def convert(input_grid):
    split_indices = (list(range(0, len(input_grid), NUM_ROWS)) +
                     [len(input_grid)])

    lines = [input_grid[start:end]
             for start, end in zip(split_indices[:-1], split_indices[1:])]

    return ','.join(convert_one_line(line) for line in lines)


def convert_one_line(input_grid):
    if len(input_grid) != NUM_ROWS:
        raise ValueError('Number of input lines is not a multiple of four')

    if len(input_grid[0]) % NUM_COLS:
        raise ValueError('Number of input columns is not a multiple of three')

    numbers = split_ocr(input_grid)
    digits = ''
    for num in numbers:
        try:
            digits += str(OCR_LIST.index(num))
        except ValueError:
            digits += '?'
    return digits

