from math import sqrt, ceil, gcd


def triplets_in_range(start, end):
    for limit in range(4, end + 1, 4):
        for x_pos, y_pos, z_pos in primitive_triplets(limit):
            alpha = x_pos
            beta = y_pos
            gamma = z_pos

            while alpha < start:
                alpha = alpha + x_pos
                beta = beta + y_pos
                gamma = gamma + z_pos

            while gamma <= end:
                yield [alpha, beta, gamma]

                alpha = alpha + x_pos
                beta = beta + y_pos
                gamma = gamma + z_pos


def euclidian_coprimes(limit):
    mean = limit // 2
    for idx in range(1, int(ceil(sqrt(mean)))):
        if mean % idx == 0:
            member = mean // idx
            if (member - idx) % 2 == 1 and gcd(member, idx) == 1:
                yield member, idx


def primitive_triplets(limit):
    """See Euclid's formula
    (https://en.wikipedia.org/wiki/Pythagorean_triple#Generating_a_triple)
    for more information
    """
    for member_1, member_2 in euclidian_coprimes(limit):
        calc_1 = member_1 ** 2
        calc_2 = member_2 ** 2

        alpha = calc_1 - calc_2
        beta = 2 * member_1 * member_2
        gamma = calc_1 + calc_2

        if alpha > beta:
            alpha, beta = beta, alpha

        yield alpha, beta, gamma


def triplets_with_sum(number):
    return [
        triplet for triplet
        in triplets_in_range(1, number // 2)
        if sum(triplet) == number
        ]

def convert(number):
    """
    Converts a number to a string according to the raindrop sounds.
    """

    result = ''
    if number % 3 == 0:
        result += 'Pling'
    if number % 5 == 0:
        result += 'Plang'
    if number % 7 == 0:
        result += 'Plong'

    if not result:
        result = str(number)
    return result

import itertools


class Corners:
    def __init__(self, idx, jdx):
        # i, j are position of corner
        self.idx = idx
        self.jdx = jdx

    def __str__(self):
        return '[' + str(self.idx) + ', ' + str(self.jdx) + ']'


# return corner on the same line
def same_line(index, list_obj):
    for corner in list_obj:
        if corner.idx == index:
            return corner
    return None


# return corner on the same column
def same_col(index, list_obj):
    for corner in list_obj:
        if corner.jdx == index:
            return corner
    return None


def search_corners(list_obj):

    return [Corners(item, element) for item in range(len(list_obj))
            for element in range(len(list_obj[item]))
            if list_obj[item][element] == '+']


# validate that 4 points form a rectangle by
# comparing distance to centroid of the rectangle for all corners
def possible_rect(quartet):
    mid_x = 0
    mid_y = 0

    for centroid in quartet:
        mid_x = mid_x + centroid.idx / 4.0
        mid_y = mid_y + centroid.jdx / 4.0

    # reference distance using first corner
    dx = abs(quartet[0].idx - mid_x)
    dy = abs(quartet[0].jdx - mid_y)

    # Check all the same distance from centroid are equals
    for idx in range(1, len(quartet)):
        if abs(quartet[idx].idx - mid_x) != dx or abs(quartet[idx].jdx - mid_y) != dy:
            return False
    return True


# validate path between two corners
def path(corner1, corner2, item):
    if corner1.idx == corner2.idx:
        for jdx in range(min(corner1.jdx + 1, corner2.jdx + 1),
                       max(corner1.jdx, corner2.jdx)):
            if item[corner1.idx][jdx] != '-' and item[corner1.idx][jdx] != '+':
                return False
        return True

    elif corner1.jdx == corner2.jdx:
        for idx in range(min(corner1.idx + 1, corner2.idx + 1),
                       max(corner1.idx, corner2.idx)):
            if item[idx][corner1.jdx] != '|' and item[idx][corner1.jdx] != '+':
                return False
        return True
    return None


# validate path of rectangle
def validate_rect(rectangle, item):
    # validate connection at every corner
    # with neighbours on the same line and col
    for idx, _ in enumerate(rectangle):
        line = same_line(rectangle[idx].idx, rectangle[0:idx] + rectangle[idx + 1:])
        column = same_col(rectangle[idx].jdx, rectangle[0:idx] + rectangle[idx + 1:])

        if not path(rectangle[idx], line, item) or not path(rectangle[idx], column, item):
            return False

    return True


# count number of rectangles inside ASCII in input lines
def rectangles(strings=''):
    rectangle_total = 0
    # test empty str
    if not strings:
        return rectangle_total

    corners = search_corners(strings)

    # no corners in str
    if not corners:
        return rectangle_total

    # all combinations of 4 corners
    quartets = list(itertools.combinations(corners, r=4))
    paths = (quartet for quartet in quartets if possible_rect(quartet))

    # validate paths
    for idx in paths:
        if validate_rect(idx, strings):
            rectangle_total += 1
    return rectangle_total

import collections
import itertools

class RelativeDistance:
    def __init__(self, family_tree):
        self.neighbors = collections.defaultdict(set)
        for parent, children in family_tree.items():
            for child in children:
                self.neighbors[parent].add(child)
                self.neighbors[child].add(parent)

            for child1, child2 in itertools.combinations(children, 2):
                self.neighbors[child1].add(child2)
                self.neighbors[child2].add(child1)

    def degree_of_separation(self, person_a, person_b):
        if person_a not in self.neighbors:
            raise ValueError("Person A not in family tree.")
        if person_b not in self.neighbors:
            raise ValueError("Person B not in family tree.")

        queue = collections.deque([(person_a, 0)])
        visited = {person_a}

        while queue:
            current, degree = queue.popleft()

            if current == person_b:
                return degree

            for neighbor in self.neighbors.get(current, []):
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, degree + 1))

        raise ValueError("No connection between person A and person B.")

NORTH, EAST, SOUTH, WEST = range(4)


class Compass:
    compass = [NORTH, EAST, SOUTH, WEST]

    def __init__(self, direction=NORTH):
        self.direction = direction

    def left(self):
        self.direction = self.compass[self.direction - 1]

    def right(self):
        self.direction = self.compass[(self.direction + 1) % 4]


class Robot:
    def __init__(self, direction=NORTH, x_pos=0, y_pos=0):
        self.compass = Compass(direction)
        self.x_pos = x_pos
        self.y_pos = y_pos

    def advance(self):
        if self.direction == NORTH:
            self.y_pos += 1
        elif self.direction == SOUTH:
            self.y_pos -= 1
        elif self.direction == EAST:
            self.x_pos += 1
        elif self.direction == WEST:
            self.x_pos -= 1

    def turn_left(self):
        self.compass.left()

    def turn_right(self):
        self.compass.right()

    def move(self, commands):
        instructions = {'A': self.advance,
                        'R': self.turn_right,
                        'L': self.turn_left}
        for cmd in commands:
            if cmd in instructions:
                instructions[cmd]()

    @property
    def direction(self):
        return self.compass.direction

    @property
    def coordinates(self):
        return (self.x_pos, self.y_pos)

class Scale:
    ASCENDING_INTERVALS = ['m', 'M', 'A']
    CHROMATIC_SCALE = ['A', 'A#', 'B', 'C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#']
    FLAT_CHROMATIC_SCALE = ['A', 'Bb', 'B', 'C', 'Db', 'D', 'Eb', 'E', 'F', 'Gb', 'G', 'Ab']
    FLAT_KEYS = ['F', 'Bb', 'Eb', 'Ab', 'Db', 'Gb', 'd', 'g', 'c', 'f', 'bb', 'eb']

    def __init__(self, tonic, intervals=None):
        self.tonic = tonic.capitalize()
        self.intervals = intervals
        self.chromatic_scale = (self.FLAT_CHROMATIC_SCALE if tonic in self.FLAT_KEYS else self.CHROMATIC_SCALE)

    def chromatic(self):
        return self._reorder_chromatic_scale()

    def interval(self, intervals):
        last_index = 0
        pitches = []
        scale = self._reorder_chromatic_scale()

        for _, interval in enumerate(intervals):
            pitches.append(scale[last_index])
            last_index += self.ASCENDING_INTERVALS.index(interval) + 1

        pitches.append(self.tonic)

        return pitches

    def _reorder_chromatic_scale(self):
        index = self.chromatic_scale.index(self.tonic)
        return  self.chromatic_scale[index:] + self.chromatic_scale[:index]

POINTS = {
    'a': 1, 'b': 3, 'c': 3, 'd': 2, 'e': 1,
    'f': 4, 'g': 2, 'h': 4, 'i': 1, 'j': 8,
    'k': 5, 'l': 1, 'm': 3, 'n': 1, 'o': 1,
    'p': 3, 'q': 10, 'r': 1, 's': 1, 't': 1,
    'u': 1, 'v': 4, 'w': 4, 'x': 8, 'y': 4,
    'z': 10
}


def score(word):
    if not word.isalpha():
        return 0
    return sum(POINTS[letter] for letter in word.lower())

def slices(series, length):
    if not series:
        raise ValueError('series cannot be empty')
    elif length == 0:
        raise ValueError('slice length cannot be zero')
    elif length < 0:
        raise ValueError('slice length cannot be negative')
    elif len(series) < length:
        raise ValueError('slice length cannot be greater than series length')

    return [series[idx:idx + length] for idx in range(len(series) - length + 1)]

def primes(limit):
    prime = [True] * (limit + 1)
    prime[0] = prime[1] = False
    for idx in range(2, int(limit ** 0.5) + 1):
        if prime[idx]:
            for edx in range(idx * idx, limit + 1, idx):
                prime[edx] = False

    return [edx for edx, idx in enumerate(prime) if idx]

def period_converter(period):
